-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), with no gaps and
-- never reused. A draft has none; voiding a claim clears it. The sheet keeps the last number given.
ALTER TABLE sheet ADD COLUMN last_claim_number INT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN claim_number INT;
-- A claim with a negative amount is a correction: it names, by number, the SETTLED claim of the
-- same person that it corrects. Null for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
-- A sheet's policy date: a claim dated before it rounds half up, one on or after it half to even.
-- Null: the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;

